#!/bin/bash\n# ============================================================================\n# Start Ollama Server for ReqTracker Development\n# ============================================================================\n# Script para iniciar Ollama con configuración optimizada para ReqTracker\n#\n# Uso:\n#   macOS/Linux: chmod +x start-ollama.sh && ./start-ollama.sh\n#   Windows: No necesario, ejecutar directamente: ollama serve\n#\n# Verificar después:\n#   curl http://localhost:11434/api/tags\n# ============================================================================\n\nset -e\n\necho \"🚀 Starting Ollama Server...\"\necho \"================================================\"\n\n# Check if Ollama is installed\nif ! command -v ollama &> /dev/null; then\n    echo \"❌ Ollama is not installed!\"\n    echo \"\\nInstall Ollama from https://ollama.ai/download\"\n    echo \"\\nMacOS: brew install ollama\"\n    echo \"Linux: curl -fsSL https://ollama.ai/install.sh | sh\"\n    exit 1\nfi\n\necho \"✅ Ollama found at: $(which ollama)\"\necho \"✅ Version: $(ollama --version)\"\n\n# Check if server is already running\nif curl -s http://localhost:11434/api/tags > /dev/null 2>&1; then\n    echo \"⚠️  Ollama server is already running on http://localhost:11434\"\n    echo \"\\nAvailable models:\"\n    curl -s http://localhost:11434/api/tags | jq '.models[].name' 2>/dev/null || echo \"   (Unable to parse models)\"\n    exit 0\nfi\n\necho \"\"\necho \"📦 Checking for required models...\"\n\n# Check if at least one model is available\nif ! ollama list 2>/dev/null | grep -q \"llama3\\|mistral\\|neural-chat\"; then\n    echo \"⚠️  No models found. Pulling llama3...\"\n    echo \"   This may take 5-10 minutes on first run.\"\n    echo \"\"\n    ollama pull llama3\nelse\n    echo \"✅ Models available:\"\n    ollama list | grep -E \"llama3|mistral|neural-chat\" || true\nfi\n\necho \"\"\necho \"================================================\"\necho \"🎯 Starting Ollama server...\"\necho \"================================================\"\necho \"\"\necho \"Server will listen on: http://localhost:11434\"\necho \"Keep this terminal open while using Continue in VS Code\"\necho \"\"\necho \"To verify it works, open another terminal and run:\"\necho \"   curl http://localhost:11434/api/tags\"\necho \"\"\necho \"Press Ctrl+C to stop the server\"\necho \"\"\n\n# Start Ollama\nollama serve\n